//! The evaluation framework of N4 §3.2–3.4: built-in function signatures, the two drivers
//! generated by `#[eval_fn]`, and the vector evaluation of an expression compiled to RPN.
//!
//! - A signature (Go's `builtinXxxSig` type) is a static [`SigDesc`]; a function node holds a
//!   [`BuiltinFunc`] = the signature + Go's `baseBuiltinFunc` fields.
//! - The body is written once, from Go's row version (`evalXxx`); `#[eval_fn]` generates the
//!   row driver and the vector driver ([`SigDrivers`]). Go's `vecEvalXxx` is not ported
//!   (M-EVAL); the vector driver reproduces its visible behavior (all arguments evaluated
//!   column by column first, NULL rows skipped).
//! - [`RpnProgram`] is the post-order form of an expression for the vector driver; it borrows
//!   the input chunk's columns instead of copying them (N4 §3.4).

pub mod rt;

use smallvec::SmallVec;
use std::borrow::Cow;

use tidb_base::Error;
use tidb_chunk::{Chunk, Column, Row};
use tidb_parser::types::{ETInt, ETReal, ETString, EvalType};
use tidb_types::collate::{self, Collator};
use tidb_types::etc::FieldType;

use crate::context::EvalContext;
use crate::expression::{EvalState, Expr, ExprRef};

/// The row driver of a signature, by result type.
pub type RowIntFn =
    fn(&BuiltinFunc, &dyn EvalContext, &EvalState, Row<'_>) -> Result<Option<i64>, Error>;
/// See [`RowIntFn`].
pub type RowRealFn =
    fn(&BuiltinFunc, &dyn EvalContext, &EvalState, Row<'_>) -> Result<Option<f64>, Error>;
/// See [`RowIntFn`].
pub type RowStringFn =
    fn(&BuiltinFunc, &dyn EvalContext, &EvalState, Row<'_>) -> Result<Option<Vec<u8>>, Error>;
/// The vector driver of a signature: `n` rows, the evaluated argument columns, the result.
pub type VecFn =
    fn(&BuiltinFunc, &dyn EvalContext, usize, &[&Column], &mut Column) -> Result<(), Error>;

/// The drivers `#[eval_fn]` generates for one signature.
#[derive(Clone, Copy)]
pub enum SigDrivers {
    /// `evalInt`.
    Int { row: RowIntFn, vec: VecFn },
    /// `evalReal`.
    Real { row: RowRealFn, vec: VecFn },
    /// `evalString`.
    String { row: RowStringFn, vec: VecFn },
}

impl SigDrivers {
    /// The evaluation type of the result.
    pub fn eval_type(&self) -> EvalType {
        match self {
            SigDrivers::Int { .. } => ETInt,
            SigDrivers::Real { .. } => ETReal,
            SigDrivers::String { .. } => ETString,
        }
    }

    fn vec(&self) -> VecFn {
        match *self {
            SigDrivers::Int { vec, .. }
            | SigDrivers::Real { vec, .. }
            | SigDrivers::String { vec, .. } => vec,
        }
    }
}

/// A built-in function signature: Go's concrete `builtinXxxSig` type (N4 §3.1).
pub struct SigDesc {
    /// The Go type name, e.g. `builtinArithmeticPlusIntSig`.
    pub name: &'static str,
    /// `tipb.ScalarFuncSig` code set by `setPbCode`.
    pub pb_code: i32,
    /// Go's `vectorized()`.
    pub vectorized: bool,
    /// The drivers.
    pub drivers: SigDrivers,
}

impl std::fmt::Debug for SigDesc {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name)
    }
}

/// A function node's signature with the `baseBuiltinFunc` fields (N4 §3.1).
#[derive(Clone)]
pub struct BuiltinFunc {
    /// The signature.
    pub sig: &'static SigDesc,
    /// `args`.
    pub args: Vec<ExprRef>,
    /// `tp`: the result type.
    pub tp: FieldType,
    /// `collation` (collationInfo of the function).
    pub collation: String,
    /// `ctor`: the collator of `collation`, resolved when the signature is built.
    ctor: &'static dyn Collator,
}

impl std::fmt::Debug for BuiltinFunc {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("BuiltinFunc")
            .field("sig", &self.sig)
            .field("args", &self.args)
            .field("tp", &self.tp)
            .field("collation", &self.collation)
            .finish()
    }
}

impl BuiltinFunc {
    /// A signature over `args` (the fields `newBaseBuiltinFunc` sets; part 2 ports that
    /// function with its type and collation derivation).
    pub fn new(
        sig: &'static SigDesc,
        args: Vec<ExprRef>,
        tp: FieldType,
        collation: String,
    ) -> BuiltinFunc {
        let ctor = collate::get_collator(&collation);
        BuiltinFunc {
            sig,
            args,
            tp,
            collation,
            ctor,
        }
    }

    /// `b.collator()`.
    // go: baseBuiltinFunc.collator L1
    #[inline]
    pub fn collator(&self) -> &'static dyn Collator {
        self.ctor
    }

    /// `b.args[i]`.
    #[inline]
    pub fn arg(&self, i: usize) -> &Expr {
        &self.args[i]
    }

    /// `evalInt`: the row driver.
    pub fn eval_int(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        row: Row<'_>,
    ) -> Result<Option<i64>, Error> {
        match self.sig.drivers {
            SigDrivers::Int { row: f, .. } => f(self, ctx, st, row),
            _ => Err(Error::plain(format!(
                "{} does not implement evalInt",
                self.sig.name
            ))),
        }
    }

    /// `evalReal`: the row driver.
    pub fn eval_real(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        row: Row<'_>,
    ) -> Result<Option<f64>, Error> {
        match self.sig.drivers {
            SigDrivers::Real { row: f, .. } => f(self, ctx, st, row),
            _ => Err(Error::plain(format!(
                "{} does not implement evalReal",
                self.sig.name
            ))),
        }
    }

    /// `evalString`: the row driver.
    pub fn eval_string(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        row: Row<'_>,
    ) -> Result<Option<Vec<u8>>, Error> {
        match self.sig.drivers {
            SigDrivers::String { row: f, .. } => f(self, ctx, st, row),
            _ => Err(Error::plain(format!(
                "{} does not implement evalString",
                self.sig.name
            ))),
        }
    }
}

/// What a body sees of its signature in one driver call: the [`BuiltinFunc`] (through
/// `Deref`) and `b.args[i].GetType(ctx)`.
///
/// Bodies take `f: &impl SigView`, so each driver gets its own copy of the body:
/// [`RowSig`] asks the argument when the body does (Go's row versions), [`VecSig`] reads the
/// types once per chunk (Go's vector versions do the same; the type of an argument cannot
/// change within a statement) and keeps them where the compiler can hold them in registers
/// for the whole loop.
pub trait SigView: std::ops::Deref<Target = BuiltinFunc> {
    /// `b.args[i].GetType(ctx)`.
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType>;
}

/// The row driver's [`SigView`].
#[derive(Clone, Copy)]
pub struct RowSig<'a> {
    f: &'a BuiltinFunc,
    ctx: &'a dyn EvalContext,
}

impl<'a> RowSig<'a> {
    /// The view of `f`.
    #[inline(always)]
    pub fn new(f: &'a BuiltinFunc, ctx: &'a dyn EvalContext) -> Self {
        RowSig { f, ctx }
    }
}

impl std::ops::Deref for RowSig<'_> {
    type Target = BuiltinFunc;
    #[inline(always)]
    fn deref(&self) -> &BuiltinFunc {
        self.f
    }
}

impl SigView for RowSig<'_> {
    #[inline(always)]
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType> {
        self.f.args[i].get_type(self.ctx)
    }
}

/// The argument types of one vector-driver call, read once per chunk.
pub struct ArgTypes<'a>(SmallVec<[Cow<'a, FieldType>; 4]>);

impl<'a> ArgTypes<'a> {
    /// Reads the argument types of `f`.
    #[inline]
    pub fn new(f: &'a BuiltinFunc, ctx: &'a dyn EvalContext) -> Self {
        ArgTypes(f.args.iter().map(|a| a.get_type(ctx)).collect())
    }
}

/// The vector driver's [`SigView`].
#[derive(Clone, Copy)]
pub struct VecSig<'a, 't> {
    f: &'a BuiltinFunc,
    types: &'a [Cow<'t, FieldType>],
}

impl<'a, 't> VecSig<'a, 't> {
    /// The view of `f` with the types of this chunk.
    #[inline(always)]
    pub fn new(f: &'a BuiltinFunc, types: &'a ArgTypes<'t>) -> Self {
        VecSig { f, types: &types.0 }
    }
}

impl std::ops::Deref for VecSig<'_, '_> {
    type Target = BuiltinFunc;
    #[inline(always)]
    fn deref(&self) -> &BuiltinFunc {
        self.f
    }
}

impl SigView for VecSig<'_, '_> {
    #[inline(always)]
    fn arg_type(&self, i: usize) -> Cow<'_, FieldType> {
        Cow::Borrowed(&*self.types[i])
    }
}

/// The arguments of a `lazy` body: evaluated when the body asks, as Go's row versions do.
pub trait Args {
    /// `len(b.args)`.
    fn len(&self) -> usize;
    /// Whether there are no arguments.
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    /// `b.args[i].EvalInt(ctx, row)`.
    fn int(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<i64>, Error>;
    /// `b.args[i].EvalReal(ctx, row)`.
    fn real(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<f64>, Error>;
    /// `b.args[i].EvalString(ctx, row)`.
    fn string(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Cow<'_, [u8]>>, Error>;
}

/// One node of an [`RpnProgram`] (post-order).
#[derive(Debug)]
pub enum RpnNode {
    /// A column of the input chunk.
    ColumnRef {
        /// `Column.Index`.
        index: usize,
    },
    /// A constant: evaluated once per chunk and filled into a column (Go `genVecFromConstExpr`).
    Constant {
        /// The constant.
        expr: ExprRef,
        /// The evaluation type the parent reads.
        as_type: EvalType,
    },
    /// A function call over the last `nargs` results.
    Call {
        /// The function node.
        func: ExprRef,
        /// The number of arguments.
        nargs: usize,
    },
}

/// An expression compiled for the vector driver (N4 §3.4). Immutable, `Send + Sync`.
#[derive(Debug)]
pub struct RpnProgram {
    nodes: Vec<RpnNode>,
    ret: EvalType,
}

/// Per-worker state of vector evaluation: reusable intermediate columns and stack.
#[derive(Default)]
pub struct RpnState {
    pool: Vec<Column>,
    stack: Vec<Slot>,
}

impl std::fmt::Debug for RpnState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RpnState")
            .field("pool", &self.pool.len())
            .finish()
    }
}

// A temporary column moves in and out of the pool; boxing it would add an allocation.
#[allow(clippy::large_enum_variant)]
enum Slot {
    Input(usize),
    Temp(Column),
}

impl RpnProgram {
    /// Compiles `e` for the vector driver.
    pub fn compile(e: &ExprRef) -> RpnProgram {
        let mut nodes = Vec::new();
        let ret = static_eval_type(e);
        compile_into(e, ret, &mut nodes);
        RpnProgram { nodes, ret }
    }

    /// The evaluation type of the result.
    pub fn ret_eval_type(&self) -> EvalType {
        self.ret
    }

    /// Evaluates the program on `input` into `result` (Go `VecEvalXxx(ctx, input, result)`).
    pub fn eval(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let mut stack = std::mem::take(&mut rpn.stack);
        stack.clear();
        let r = self.eval_inner(ctx, st, rpn, &mut stack, input, result);
        for s in stack.drain(..) {
            if let Slot::Temp(c) = s {
                rpn.pool.push(c);
            }
        }
        rpn.stack = stack;
        r
    }

    fn eval_inner(
        &self,
        ctx: &dyn EvalContext,
        st: &EvalState,
        rpn: &mut RpnState,
        stack: &mut Vec<Slot>,
        input: &Chunk,
        result: &mut Column,
    ) -> Result<(), Error> {
        let n = input.num_rows();
        let last = self.nodes.len() - 1;
        for (pos, node) in self.nodes.iter().enumerate() {
            match node {
                RpnNode::ColumnRef { index } => {
                    if pos == last {
                        // The whole expression is a column: Go copies it into the result.
                        let dst = std::mem::replace(result, rt::empty_column());
                        *result = input
                            .column(*index)
                            .copy_reconstruct(input.sel(), Some(dst));
                        return Ok(());
                    }
                    match input.sel() {
                        None => stack.push(Slot::Input(*index)),
                        Some(sel) => {
                            let tmp = rpn.pool.pop();
                            stack.push(Slot::Temp(
                                input.column(*index).copy_reconstruct(Some(sel), tmp),
                            ));
                        }
                    }
                }
                RpnNode::Constant { expr, as_type } => {
                    if pos == last {
                        return rt::fill_constant(ctx, st, expr, *as_type, n, result);
                    }
                    let mut col = rpn.pool.pop().unwrap_or_else(rt::empty_column);
                    let r = rt::fill_constant(ctx, st, expr, *as_type, n, &mut col);
                    stack.push(Slot::Temp(col));
                    r?;
                }
                RpnNode::Call { func, nargs } => {
                    let f = &func
                        .as_scalar_function()
                        .expect("Call node holds a ScalarFunction")
                        .function;
                    let base = stack.len() - nargs;
                    let mut out = if pos == last {
                        None
                    } else {
                        Some(rpn.pool.pop().unwrap_or_else(rt::empty_column))
                    };
                    let r = {
                        let cols: rt::ArgCols<'_> = stack[base..]
                            .iter()
                            .map(|s| match s {
                                Slot::Input(i) => input.column(*i),
                                Slot::Temp(c) => c,
                            })
                            .collect();
                        let dst = match out.as_mut() {
                            Some(c) => c,
                            None => &mut *result,
                        };
                        (f.sig.drivers.vec())(f, ctx, n, &cols, dst)
                    };
                    for s in stack.drain(base..) {
                        if let Slot::Temp(c) = s {
                            rpn.pool.push(c);
                        }
                    }
                    match out {
                        Some(c) => stack.push(Slot::Temp(c)),
                        None => return r,
                    }
                    r?;
                }
            }
        }
        unreachable!("an RPN program ends with its root")
    }
}

fn compile_into(e: &ExprRef, as_type: EvalType, nodes: &mut Vec<RpnNode>) {
    match &**e {
        Expr::Column(c) => nodes.push(RpnNode::ColumnRef {
            index: c.index as usize,
        }),
        Expr::Constant(_) | Expr::CorrelatedColumn(_) => nodes.push(RpnNode::Constant {
            expr: e.clone(),
            as_type,
        }),
        Expr::ScalarFunction(sf) => {
            for a in &sf.function.args {
                compile_into(a, static_eval_type(a), nodes);
            }
            nodes.push(RpnNode::Call {
                func: e.clone(),
                nargs: sf.function.args.len(),
            });
        }
    }
}

/// The evaluation type of `e`'s `RetType` known at build time (a parameter marker's type is
/// fixed when the plan is built, so the field is enough here).
fn static_eval_type(e: &Expr) -> EvalType {
    match e {
        Expr::Column(c) => c.ret_type.eval_type(),
        Expr::CorrelatedColumn(c) => c.column.ret_type.eval_type(),
        Expr::Constant(c) => c.ret_type.eval_type(),
        Expr::ScalarFunction(f) => f.ret_type.eval_type(),
    }
}
